{
  "regions": [
    {
      "id": "r3",
      "type": "verse",
      "lines": [
        {
          "n": 1,
          "text": "तानीन्द्रियाणि सकलानि तदेव कर्म",
          "end": "line"
        },
        {
          "n": 2,
          "text": "सा बुद्धिरप्रतिहता वचनं तदेव ।",
          "end": "line"
        },
        {
          "n": 3,
          "text": "अर्थोष्मणा विरहितः पुरुषः स एव",
          "end": "line"
        },
        {
          "n": 4,
          "text": "त्वन्यः क्षणेन भवतीति विचित्रमेतत् ॥ ४० ॥",
          "end": "space"
        }
      ],
      "uncertain": false,
      "note": null
    },
    {
      "id": "r4",
      "type": "commentary",
      "lines": [
        {
          "n": 1,
          "text": "सकलानि अक्षतानि इन्द्रियाणि तानि यथापूर्वमवस्थितान्येव । अप्रतिहता",
          "end": "space"
        },
        {
          "n": 2,
          "text": "केनाप्यंशेनाहीना बुद्धिः सैव । पुरुषोपि स एव । अर्थस्योष्मा अर्थोष्मा तेन",
          "end": "space"
        },
        {
          "n": 3,
          "text": "विरहितः क्षणेनान्यो भवतीति एतद् विचित्रमित्यन्वयः । वसन्ततिलका वृत्तम् ।",
          "end": "space"
        }
      ],
      "uncertain": false,
      "note": null
    },
    {
      "id": "r5",
      "type": "lead_in",
      "lines": [
        {
          "n": 1,
          "text": "अधुनार्थनिष्ठा एव सर्वे गुणा इत्याह—",
          "end": "space"
        }
      ],
      "uncertain": false,
      "note": null
    },
    {
      "id": "r6",
      "type": "verse",
      "lines": [
        {
          "n": 1,
          "text": "यस्यास्ति वित्तं स नरः कुलीनः",
          "end": "line"
        },
        {
          "n": 2,
          "text": "स पण्डितः सः श्रुतवान्गुणज्ञः ।",
          "end": "line"
        },
        {
          "n": 3,
          "text": "स एव वक्ता स च दर्शनीयः",
          "end": "line"
        },
        {
          "n": 4,
          "text": "सर्वे गुणाः काञ्चनमाश्रयन्ते ॥ ४१ ॥",
          "end": "space"
        }
      ],
      "uncertain": false,
      "note": null
    },
    {
      "id": "r7",
      "type": "commentary",
      "lines": [
        {
          "n": 1,
          "text": "कुले जातः कुलीनः । अभिजनवान् । कुलात्खः इति खप्रत्ययः । श्रुतं",
          "end": "space"
        },
        {
          "n": 2,
          "text": "श्रवणं । नपुंसके भावे क्तः । तदस्यास्तीति श्रुतवान् ज्ञानसंपन्नः । आश्रयन्ते ।",
          "end": "space"
        },
        {
          "n": 3,
          "text": "उक्तगुणरहित्येपीत्यर्थः । काव्यलिङ्गमलंकारः । वृत्तमुपजातिः । अस्य समानार्थः",
          "end": "space"
        },
        {
          "n": 4,
          "text": "श्लोकः–यस्यार्थास्तस्य मित्राणि यस्यार्थास्तस्य बान्धवाः । यस्यार्थाः स पुमाँ-",
          "end": "hyphen"
        },
        {
          "n": 5,
          "text": "ल्लोके यस्यार्थाः स च पण्डितः । अपरश्च-ब्रह्महापि नरः पूज्यो यस्यास्ति",
          "end": "space"
        },
        {
          "n": 6,
          "text": "विपुलं धनम् । शशिनस्तुल्यवंशोपि निर्धनः परिभूयते ॥",
          "end": "space"
        }
      ],
      "uncertain": false,
      "note": null
    },
    {
      "id": "r8",
      "type": "lead_in",
      "lines": [
        {
          "n": 1,
          "text": "अथार्थादेर्विनाशप्रकारमाह—",
          "end": "space"
        }
      ],
      "uncertain": false,
      "note": null
    },
    {
      "id": "r9",
      "type": "verse",
      "lines": [
        {
          "n": 1,
          "text": "दौर्मन्त्र्या[१]न्नृपतिर्विनश्यति यतिः सङ्गात्सुतो लालना-",
          "end": "hyphen"
        },
        {
          "n": 2,
          "text": "द्विप्रोनध्यनात्कुलं कुतनयाच्छीलं खलोपासनात् ।",
          "end": "line"
        },
        {
          "n": 3,
          "text": "ह्रीर्मद्यादनवेक्षणादपि कृषिः स्नेहः प्रवासाश्रया-",
          "end": "hyphen"
        },
        {
          "n": 4,
          "text": "न्मैत्री चाप्रणयात्समृद्धिरनयात्त्याग[२]प्रमादाद्धनम् ॥ ४२ ॥",
          "end": "space"
        }
      ],
      "uncertain": false,
      "note": null
    },
    {
      "id": "r10",
      "type": "commentary",
      "lines": [
        {
          "n": 1,
          "text": "दुष्टो मन्त्रः षाड्गुण्यचिन्तालक्षणः यस्य स दुर्मन्त्रः । दुष्टा मन्त्रिणो यस्य",
          "end": "space"
        },
        {
          "n": 2,
          "text": "इति वा । तस्य भावो दौर्मन्त्र्यं । तस्मात् । विनश्यति । परै राज्याद्यपहरणात् ।",
          "end": "space"
        },
        {
          "n": 3,
          "text": "तदुक्तं—दुर्मन्त्री राज्यनाशायेति । यतिः सङ्गात् । तस्य कामक्रोधादिहेतुत्वात् ।",
          "end": "space"
        }
      ],
      "uncertain": false,
      "note": null
    },
    {
      "id": "r11",
      "type": "footnote",
      "lines": [
        {
          "n": 1,
          "text": "१ दुर्मन्त्रात्.",
          "end": "space"
